<?php declare(strict_types=1); require __DIR__.'/../config/config.php'; $db=db(); $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){try{$a=$_POST['action']??'';if($a==='bulk_add'){ $rows=json_decode($_POST['rows']??'[]',true)?:[];if(!$rows)throw new RuntimeException('Add at least one customer.');$db->beginTransaction();$q=$db->prepare('INSERT INTO customers(name,phone,address) VALUES(?,?,?)');$n=0;foreach($rows as $r){$name=trim((string)($r['name']??''));if($name==='')continue;$q->execute([$name,trim((string)($r['phone']??'')),trim((string)($r['address']??''))]);$n++;}$db->commit();header('Location: customers.php?saved='.$n);exit;}if($a==='pay'){$cid=(int)$_POST['customer_id'];$amount=(float)$_POST['amount'];if($amount<=0)throw new RuntimeException('Enter a valid payment amount.');$q=$db->prepare("SELECT COALESCE(SUM(total-paid),0) FROM sales WHERE customer_id=? AND payment_method='credit'");$q->execute([$cid]);$due=(float)$q->fetchColumn();if($amount>$due+0.0001)throw new RuntimeException('Payment cannot exceed outstanding credit.');$db->beginTransaction();$remaining=$amount;$q=$db->prepare("SELECT id,total,paid FROM sales WHERE customer_id=? AND payment_method='credit' AND total>paid ORDER BY id");$q->execute([$cid]);foreach($q as $s){$open=(float)$s['total']-(float)$s['paid'];$take=min($remaining,$open);if($take>0){$db->prepare('UPDATE sales SET paid=paid+? WHERE id=?')->execute([$take,$s['id']]);$remaining-=$take;}if($remaining<=0)break;}$db->commit();header('Location: customers.php?paid=1');exit;}}catch(Throwable $e){if($db->inTransaction())$db->rollBack();$error=$e->getMessage();}}$rows=$db->query("SELECT c.*,COALESCE((SELECT SUM(s.total-s.paid) FROM sales s WHERE s.customer_id=c.id AND s.payment_method='credit'),0) due,COALESCE((SELECT SUM(s.total) FROM sales s WHERE s.customer_id=c.id),0) sales_total FROM customers c ORDER BY c.name")->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Customers</title><link rel="stylesheet" href="style.css"><style>.bulk{overflow:auto}.bulk table{min-width:700px}.bulk input{width:100%;box-sizing:border-box;padding:8px;border:1px solid #cbd5e1;border-radius:6px}.actions{display:flex;gap:10px;margin-top:12px}.pay{display:flex;gap:6px}.pay input{width:110px;padding:8px}.remove{border:0;background:none;color:#dc2626;font-size:20px;cursor:pointer}</style></head><body><header><div class="brand">💊 <?=e(APP_NAME)?></div><nav><a href="index.php">Dashboard</a><a href="pos.php">POS</a><a class="active" href="manage.php">Management</a></nav><div class="user-info">👤 <?=e(current_user()['username']??'')?> · <a href="logout.php">Logout</a></div></header><main><div class="page-title"><div><div class="eyebrow">CUSTOMERS</div><h1>Customers</h1><p>Add multiple customers quickly, then manage credit balances.</p></div></div><?php if($error):?><div class="error">✕ <?=e($error)?></div><?php endif;?><?php if(isset($_GET['saved'])):?><div class="success">✓ <?=e($_GET['saved'])?> customers saved.</div><?php endif;?><?php if(isset($_GET['paid'])):?><div class="success">✓ Customer payment recorded.</div><?php endif;?><section class="panel"><h2>➕ Bulk Add Customers</h2><div class="bulk"><table><thead><tr><th>Name *</th><th>Phone</th><th>Address</th><th></th></tr></thead><tbody id="new"></tbody></table></div><div class="actions"><button type="button" class="btn" id="add">＋ Add Row</button><button type="button" class="btn" id="save">💾 Save All Customers</button></div></section><section class="panel"><h2>Customer Balances</h2><div class="bulk"><table><tr><th>Customer</th><th>Phone</th><th>Total Sales</th><th>Credit Due</th><th>Payment</th></tr><?php foreach($rows as $r):$due=(float)$r['due'];?><tr><td><b><?=e($r['name'])?></b></td><td><?=e($r['phone'])?></td><td>Rs. <?=money((float)$r['sales_total'])?></td><td><b>Rs. <?=money($due)?></b></td><td><?php if($due>0):?><form method="post" class="pay"><input type="hidden" name="action" value="pay"><input type="hidden" name="customer_id" value="<?=$r['id']?>"><input name="amount" type="number" min="0.01" max="<?=e((string)$due)?>" step="0.01" placeholder="Amount" required><button class="btn">Receive</button></form><?php else:?>Clear<?php endif;?></td></tr><?php endforeach;?></table></div></section></main><script>const body=document.getElementById('new');function row(){const tr=document.createElement('tr');tr.innerHTML='<td><input data-k="name" placeholder="Customer name"></td><td><input data-k="phone" placeholder="Phone"></td><td><input data-k="address" placeholder="Address"></td><td><button type="button" class="remove" onclick="this.closest(\'tr\').remove()">×</button></td>';body.appendChild(tr)}document.getElementById('add').onclick=row;document.getElementById('save').onclick=()=>{const rows=[...body.children].map(tr=>{const o={};tr.querySelectorAll('[data-k]').forEach(x=>o[x.dataset.k]=x.value);return o}).filter(x=>x.name.trim());if(!rows.length)return alert('Add at least one customer.');const f=document.createElement('form');f.method='post';f.innerHTML='<input name="action" value="bulk_add"><input name="rows">';f.querySelector('[name=rows]').value=JSON.stringify(rows);document.body.appendChild(f);f.submit()};row();row();</script></body></html>